use hs_loop::repl::{parse_command,ReplCommand};
#[test]fn plan_command_is_builtin_not_skill_or_untrusted_model_goal(){assert!(!matches!(parse_command("/plan"),ReplCommand::Unknown(_)|ReplCommand::Goal(_)));assert!(!matches!(parse_command("/plan off"),ReplCommand::Unknown(_)|ReplCommand::Goal(_)));assert!(matches!(parse_command("/planet"),ReplCommand::Unknown(_)));assert!(matches!(parse_command("/planets do work"),ReplCommand::Unknown(_)));}
fn rig(d:&std::path::Path,plan:bool)->hs_loop::repl::ReplSession{let cfg=d.join("rig");std::fs::write(&cfg,format!("{}\n[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",if plan{"[plan]\nsection='Host planning guide.'"}else{""},env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();hs_loop::repl::ReplSession::load(&cfg,&d.join("run"),false,Some(1)).unwrap()}
#[test]fn host_plan_command_keeps_message_source_separate_from_controls(){let d=tempfile::tempdir().unwrap();let mut s=rig(d.path(),true);let r=s.host_plan_command("Fix parser").unwrap();assert_eq!(r["text"],"Plan mode on. Use /plan off to leave.");assert_eq!(r["message"],"Fix parser");assert_eq!(r["mode"]["active"],true);assert_eq!(s.host_plan_command("").unwrap()["text"],"Entering plan mode (applies from the next step). Use /plan off to leave.");assert_eq!(s.host_plan_command("off").unwrap()["text"],"Plan mode off.");assert_eq!(s.host_plan_command("off").unwrap()["text"],"Plan mode is already inactive.");assert!(!hs_loop::plan_mode::active(d.path()));}
#[test]fn absent_deployment_guide_fails_closed_before_plan_control_mutation(){let d=tempfile::tempdir().unwrap();let mut s=rig(d.path(),false);assert!(s.host_plan_command("Fix parser").is_err());assert_eq!(s.plan_view()["active"],false);assert_eq!(s.host_plan_command("off").unwrap()["text"],"Plan mode is already inactive.");}
#[test]fn plan_palette_is_exact_builtin_and_discoverable(){let s=hs_loop::tui::command_lookup("plan").unwrap();assert_eq!(s.args,Some("[off|message]"));assert!(hs_loop::tui::TUI_HELP.contains("/plan"));assert!(hs_loop::repl::command_completions("/pl").contains(&"/plan".to_string()));}
